  const viewState = state.assessment ? state : previousResult;
  const assessment = viewState?.assessment;
  $('result').hidden = !assessment;
  $('clarification').hidden = true;
  $('provisional').hidden = true;
  brief = null;
  $('brief').textContent = '';
